package app.sentier.domain

import java.util.Base64

/**
 * Terres émergées en grille de 2 degrés, pour dessiner la carte du monde en pointillés.
 * Calculée à partir des contours de Natural Earth (domaine public), de 84° N à 58° S.
 */
object WorldMask {
    const val STEP = 2.0
    const val LAT_TOP = 84.0
    const val LAT_BOTTOM = -58.0
    const val COLS = 180
    const val ROWS = 71

    private const val DATA = ""

    private val bits: ByteArray by lazy { Base64.getDecoder().decode(DATA) }

    /** Vrai si la case [col], [row] (0 en haut à gauche, à 180° O et 84° N) est sur la terre ferme. */
    fun isLand(col: Int, row: Int): Boolean {
        if (col !in 0 until COLS || row !in 0 until ROWS) return false
        val i = row * COLS + col
        return (bits[i / 8].toInt() shr (7 - i % 8)) and 1 == 1
    }
}
